import demoIds from "./demo-ids.json";

/**
 * The demo seed's ids (backend/scripts/seed_demo.py): every seeded row's UUID is UUIDv5 of its mock fixture id,
 * so the two can be translated both ways. On a live session the frontend keeps the fixture ids: the modules
 * still on mocks (candidates, jobs…) then find a seeded firm's rows, and only the live adapters translate, at
 * the edge. An id that isn't a seeded row's (a firm created live, a new user) passes through unchanged.
 * Generated by ./demo-ids.test.ts; the backend's test checks it against seed_demo.demo_id.
 */
const toBackend: Readonly<Record<string, string>> = demoIds;
const fromBackend: Readonly<Record<string, string>> = Object.fromEntries(Object.entries(demoIds).map(([fixture, uuid]) => [uuid, fixture]));

export const toBackendId = (id: string): string => toBackend[id] ?? id;
export const fromBackendId = (id: string): string => fromBackend[id] ?? id;
